package com.courseqa.controller;
import com.courseqa.model.dto.*;import com.courseqa.service.ChapterSuggestionService;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/documents") @CrossOrigin public class ChapterSuggestionController {private final ChapterSuggestionService service;public ChapterSuggestionController(ChapterSuggestionService service){this.service=service;}@GetMapping("/{documentId}/chapter-suggestions")public ApiResponse<List<ChapterSuggestionDto.ReviewItem>> get(@PathVariable UUID documentId){return ApiResponse.ok(service.getOrGenerate(documentId));}@PutMapping("/{documentId}/chapter-suggestions")public ApiResponse<List<ChapterSuggestionDto.ReviewItem>> confirm(@PathVariable UUID documentId,@RequestBody ChapterSuggestionDto.ConfirmRequest request){return ApiResponse.ok(service.confirm(documentId,request));}}
